const input = $json ?? {};
const objective = typeof input.objective === 'string' ? input.objective.trim() : '';
const priority = input.priority === undefined || input.priority === null || input.priority === '' ? 50 : Number(input.priority);
const type = typeof input.type === 'string' && input.type.trim() ? input.type.trim() : 'general';
const createdBy = typeof input.created_by === 'string' && input.created_by.trim() ? input.created_by.trim() : 'user';
const constraints = input.constraints && typeof input.constraints === 'object' ? input.constraints : {};
const inputData = input.input_data && typeof input.input_data === 'object' ? input.input_data : {};
return [{json:{objective,type,priority,created_by:createdBy,constraints,input_data:inputData,intake_metadata:{received_at:new Date().toISOString(),source:input.source||'manual',request_id:input.request_id||null}}}];

const input=$json??{}; const errors=[];
if(!input.objective||typeof input.objective!=='string') errors.push('OBJECTIVE_REQUIRED');
else if(input.objective.trim().length<3) errors.push('OBJECTIVE_TOO_SHORT');
if(input.priority!==undefined&&(!Number.isInteger(Number(input.priority))||Number(input.priority)<0||Number(input.priority)>100)) errors.push('INVALID_PRIORITY');
return [{json:{...input,valid:errors.length===0,validation_errors:errors}}];
